#include <iostream>
using namespace std;

// @pre n >= 0
// @post retorna el nombre de parells de dígits consecutius de n
//       on el dígit de l'esquerra és estrictament menor que el de la dreta
int pujades(int n) {
    int res = 0;
    int dreta = n%10;
    n = n/10;
    while (n > 0) {
        int esq = n%10;
        if (esq < dreta) ++res;
        dreta = esq;
        n = n/10;
    }
    return res;
}

int main() {
    int k;
    cin >> k;
    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        cout << pujades(x) << endl;
    }
}

