#include <iostream>
using namespace std;

// @pre x >= 0 i y >= 0
// @post retorna el nombre de posicions (alineades per la dreta, amb zeros
//       a l'esquerra del nombre més curt) on x i y tenen dígit diferent
int difs(int x, int y) {
    if (x == 0 and y == 0) return 0;
    int d = 0;
    if (x%10 != y%10) d = 1;
    return d + difs(x/10, y/10);
}

int main() {
    int k;
    cin >> k;
    for (int i = 0; i < k; ++i) {
        int x, y;
        cin >> x >> y;
        cout << difs(x, y) << endl;
    }
}

