#include <iostream>

int     pujades(int n)
{
        int     *pn;
        int     pujades;

        pn = &n;
        pujades = 0;
        while (*pn)
        {
                if (*pn != *pn + 1)
                        (*pn)++;
                else if (*pn <= *pn + 1 && *pn <= *pn + 2)
                        (*pn)++;
                else
                        pujades += 1;
                pn++;
        }
        return (pujades);
}

int     main(void)
{
        int     nbr[4] = {3, 1213, 7, 9876};
        int     *pnbr;

        pnbr = &nbr[0];
        while (*pnbr)
        {
                std::cout << pujades(pnbr[0]) << '\n';
                pnbr++;
        }
        return (0);
}
